import { Box, Flex, Text, VStack } from '@chakra-ui/react'
import { useVirtualizer, VirtualItem } from '@tanstack/react-virtual'
import React, { useEffect } from 'react'
import Table from './Table'

// ------------------ 公共类型 ------------------

export interface Column<T> {
  key: keyof T | string // 列对应的字段名（允许是 T 的键，也可自定义）
  title: React.ReactNode
  render?: (row: T) => React.ReactNode // 可选的自定义渲染函数
  sticky?: boolean // 如果需要 sticky，给列单独标记
}

export interface VirtualTableProps<T> {
  columns: Column<T>[]
  data: T[]
  rowHeight?: number
  overscan?: number
  stickyHeaderTop: string | number
  gridTemplateColumns: any
  columnGap?: string
  justify?: string
  px?: string
  bg?: string
  isApp?: boolean
  scrollWidth?: string | number
  onRowClick?: (item: T) => void
  isLoading?: boolean
  rowKey?: string | ((item: T) => string)
  rowStyle?: React.CSSProperties
  scrollContainerSelector?: string // 新增：滚动容器选择器
}

// ------------------ VirtualTable 主组件 ------------------

export default function VirtualTable<T>({
  columns,
  data,
  rowHeight = 66,
  overscan = 20,
  stickyHeaderTop = 0,
  gridTemplateColumns,
  columnGap = '12px',
  px = '0 16px',
  bg = 'bg_primary',
  isApp = false,
  isLoading = false,
  scrollWidth = '830px',
  justify = '',
  onRowClick = () => {},
  rowKey = 'coinType',
  rowStyle = {},
  scrollContainerSelector = '.scroll-container' // 默认选择器
}: VirtualTableProps<T>) {
  const rowVirtualizer = useVirtualizer({
    count: data?.length || 0,
    getScrollElement: () => document.querySelector(scrollContainerSelector) as HTMLElement,
    estimateSize: () => rowHeight,
    overscan
  })

  useEffect(() => {
    rowVirtualizer.measure()
  }, [data, rowVirtualizer])

  // 添加滚动容器存在性检查
  useEffect(() => {
    const scrollContainer = document.querySelector(scrollContainerSelector)
    if (!scrollContainer) {
      console.warn(`Scroll container with selector "${scrollContainerSelector}" not found`)
    }
  }, [scrollContainerSelector])

  const renderHeader = () => (
    <Box
      display="grid"
      w="100%"
      gridTemplateColumns={gridTemplateColumns}
      h="36px"
      columnGap={isApp ? '0px' : columnGap}
      p={isApp ? 0 : px}
      position={isApp ? 'unset' : 'sticky'}
      top={stickyHeaderTop}
      zIndex="10"
      bg={bg}
    >
      {columns.map((col, index) => (
        <Flex
          key={String(col.key)}
          align="center"
          justify={index === 0 ? 'flex-start' : index === columns.length - 1 ? 'flex-end' : justify || 'flex-start'}
          position={isApp && col.sticky ? 'sticky' : 'static'}
          left="0"
          right="0"
          bg={isApp && col.sticky ? bg : 'inherit'}
          zIndex={isApp && col.sticky ? 2 : 1}
          pl={isApp && !col.sticky ? '12px' : '0px'}
        >
          {col.title}
        </Flex>
      ))}
    </Box>
  )

  const renderVirtualRows = () => (
    <Box w="100%" h={`${rowVirtualizer.getTotalSize()}px`} pos="relative" minHeight="500px">
      {rowVirtualizer.getVirtualItems().map(virtualRow => {
        const item = data[virtualRow.index]
        const key = typeof rowKey === 'function' ? rowKey(item) : ((item as any)?.[rowKey] ?? virtualRow.index)

        return (
          <RowItem<T>
            key={key}
            item={item}
            columns={columns}
            virtualRow={virtualRow}
            gridTemplateColumns={gridTemplateColumns}
            onRowClick={onRowClick}
            isApp={isApp}
            justify={justify}
            bg={bg}
            rowHeight={rowHeight}
            px={px}
            columnGap={columnGap}
            style={rowStyle}
          />
        )
      })}
    </Box>
  )

  const renderContent = () => {
    if (isLoading) {
      return (
        <Table<any>
          rowKey={rowKey}
          columns={columns}
          dataSource={data}
          skeletonLength={10}
          loading={true}
          rowStyle={{ height: `${rowHeight}px`, ...rowStyle }}
        />
      )
    }

    if (isApp) {
      return (
        <Box w="100%" overflowX="auto" bg={bg}>
          <Box w={scrollWidth}>
            {renderHeader()}
            {renderVirtualRows()}
          </Box>
        </Box>
      )
    }

    return (
      <VStack gap="0">
        {renderHeader()}
        {renderVirtualRows()}
      </VStack>
    )
  }

  return (
    <VStack w="100%" gap="0" align="stretch">
      {renderContent()}
    </VStack>
  )
}

// ------------------ RowItem 子组件 ------------------

interface RowItemProps<T> {
  item: T
  columns: Column<T>[]
  virtualRow: VirtualItem
  onRowClick: (item: T) => void
  bg: string
  justify: string
  isApp?: boolean
  gridTemplateColumns: string
  rowHeight: number
  px: string
  columnGap: string
  style: React.CSSProperties
}

function RowItem<T>({
  item,
  columns,
  virtualRow,
  onRowClick,
  bg,
  justify,
  isApp = false,
  gridTemplateColumns,
  rowHeight,
  px,
  columnGap,
  style
}: RowItemProps<T>) {
  return (
    <Box
      pos="absolute"
      top={`${virtualRow.start}px`}
      left={0}
      w="100%"
      style={{
        ...style,
        height: `${rowHeight}px`
      }}
      display="grid"
      cursor="pointer"
      columnGap={isApp ? '0px' : columnGap}
      gridTemplateColumns={gridTemplateColumns}
      borderRadius="12px"
      p={{ base: '0', lg: px }}
      _hover={{
        bg: isApp ? 'auto' : 'primary_opacity.10'
      }}
      onClick={() => onRowClick(item)}
    >
      {columns.map((col, index) => (
        <Flex
          key={String(col.key)}
          align="center"
          justify={index === 0 ? 'flex-start' : index === columns.length - 1 ? 'flex-end' : justify || 'flex-start'}
          position={isApp && col.sticky ? 'sticky' : 'static'}
          right={0}
          left={0}
          bg={isApp ? bg : 'unset'}
          zIndex={isApp && col.sticky ? 2 : 1}
          h="100%"
          pl={isApp && !col.sticky ? '12px' : '0px'}
        >
          {col.render ? (
            col.render(item)
          ) : (
            <Text fontSize="14px" fontWeight="500" color="text_caption">
              {(item as any)?.[col.key as keyof T] as string | number}
            </Text>
          )}
        </Flex>
      ))}
    </Box>
  )
}
